// Leptid — UI toolkit implementation (fonts, widgets).
#include "ui/ui.h"

#define STB_TRUETYPE_IMPLEMENTATION
#define STBTT_STATIC
#include "stb_truetype.h"

#include <algorithm>
#include <cstring>

// font bytes generated by the build into bin/fontdata.cpp
namespace leptid_embed {
extern const unsigned char DejaVuSans_font[];
extern unsigned int DejaVuSans_font_len;
extern const unsigned char DejaVuSansBold_font[];
extern unsigned int DejaVuSansBold_font_len;
}

namespace leptid {

const Theme& Theme::get() {
    static Theme t;
    return t;
}

bool inRect(float px, float py, int x, int y, int w, int h) {
    return px >= x && py >= y && px < x + w && py < y + h;
}

// ---------------- font ----------------
bool Font::bake(const unsigned char* ttf, unsigned len, float pixelHeight, Image& atlas,
                std::vector<Glyph>& glyphs) {
    stbtt_fontinfo info;
    if (!stbtt_InitFont(&info, ttf, 0)) return false;
    (void)len;
    glyphs.clear();
    // ASCII: 32..126
    const int first = 32, last = 127;
    int count = last - first;
    int atlasW = 512;
    int atlasH = (int)pixelHeight * 3 + 8;
    atlas.create(atlasW, atlasH);
    atlas.clear(Color(0, 0, 0, 0));
    glyphs.assign(count, Glyph{});
    float scale = stbtt_ScaleForPixelHeight(&info, pixelHeight);
    int ascent, descent, lineGap;
    stbtt_GetFontVMetrics(&info, &ascent, &descent, &lineGap);
    float aStep = (ascent - descent + lineGap) * scale;
    float yCursor = 2;
    float xCursor = 1;
    for (int c = first; c < last; ++c) {
        int gw, gh, ox, oy;
        unsigned char* rendered = stbtt_GetCodepointBitmap(&info, 0, scale, c, &gw, &gh, &ox, &oy);
        if (!rendered) continue;
        if (xCursor + gw + 1 >= atlasW) { xCursor = 1; yCursor += aStep + 2; }
        if (yCursor + gh + 2 >= atlasH) { stbtt_FreeBitmap(rendered, nullptr); break; }
        for (int yy = 0; yy < gh; ++yy)
            for (int xx = 0; xx < gw; ++xx)
                atlas.at(xCursor + xx, yCursor + yy) = ((uint32_t)rendered[yy * gw + xx] << 24) | 0xFFFFFFu;
        int adv = 0, lsb = 0;
        stbtt_GetCodepointHMetrics(&info, c, &adv, &lsb);
        Glyph g;
        g.atlasX = (int)xCursor;
        g.atlasY = (int)yCursor;
        g.w = gw;
        g.h = gh;
        g.advance = adv * scale;
        g.x0 = (float)ox;
        g.y0 = (float)oy;
        glyphs[c - first] = g;
        xCursor += gw + 1;
        stbtt_FreeBitmap(rendered, nullptr);
    }
    size_ = pixelHeight;
    return true;
}

bool Font::load(const unsigned char* ttf, unsigned len, float pixelHeight) {
    if (!bake(ttf, len, pixelHeight, atlas_, glyphs_)) return false;
    bake(ttf, len, pixelHeight, atlasBold_, glyphsBold_); // same font (no separate bold face embedded per size; acceptable)
    return true;
}

float Font::textWidth(const std::string& text) const {
    float w = 0;
    for (unsigned char c : text) {
        if (c < 32 || c >= 127) { w += size_ * 0.3f; continue; }
        const Glyph& g = glyphs_[(size_t)c - 32];
        w += g.w > 0 ? g.advance : size_ * 0.3f;
    }
    return w;
}

void Font::drawInternal(Image& fb, const std::string& text, float x, float y, Color c,
                        const Image& atlas, const std::vector<Glyph>& glyphs) const {
    float cx = x;
    for (unsigned char ch : text) {
        if (ch == '\n') { continue; }
        if (ch < 32 || ch >= 127) { cx += size_ * 0.3f; continue; }
        const Glyph& g = glyphs[(size_t)ch - 32];
        if (g.w > 0) {
            // blend glyph alpha onto fb
            int dx = (int)std::lround(cx + g.x0);
            int dy = (int)std::lround(y + g.y0);
            for (int yy = 0; yy < g.h; ++yy) {
                int fy = dy + yy;
                if (fy < 0 || fy >= fb.h) continue;
                for (int xx = 0; xx < g.w; ++xx) {
                    int fx = dx + xx;
                    if (fx < 0 || fx >= fb.w) continue;
                    uint32_t sp = atlas.at(g.atlasX + xx, g.atlasY + yy);
                    uint8_t a = (uint8_t)(sp >> 24);
                    if (a == 0) continue;
                    float sa = (a / 255.0f) * (c.a / 255.0f);
                    Color d = Color::unpack(fb.at(fx, fy));
                    float da = d.a / 255.0f;
                    float outA = sa + da * (1 - sa);
                    if (outA < 1e-5f) { fb.at(fx, fy) = 0; continue; }
                    float oR = (c.r * sa + d.r * da * (1 - sa)) / outA;
                    float oG = (c.g * sa + d.g * da * (1 - sa)) / outA;
                    float oB = (c.b * sa + d.b * da * (1 - sa)) / outA;
                    fb.at(fx, fy) = Color::fromFloats(oR / 255.0f, oG / 255.0f, oB / 255.0f, outA).pack();
                }
            }
        }
        cx += g.w > 0 ? g.advance : size_ * 0.3f;
    }
}

void Font::draw(Image& fb, const std::string& text, float x, float y, Color color) const {
    drawInternal(fb, text, x, y, color, atlas_, glyphs_);
}
void Font::drawBold(Image& fb, const std::string& text, float x, float y, Color color) const {
    drawInternal(fb, text, x, y, color, atlasBold_, glyphsBold_);
}

Font& uiFont() {
    static Font f;
    static bool init = false;
    if (!init) {
        f.load(leptid_embed::DejaVuSans_font, leptid_embed::DejaVuSans_font_len, 13.0f);
        init = true;
    }
    return f;
}
Font& uiFontBig() {
    static Font f;
    static bool init = false;
    if (!init) {
        f.load(leptid_embed::DejaVuSansBold_font, leptid_embed::DejaVuSansBold_font_len, 16.0f);
        init = true;
    }
    return f;
}

// ---------------- Ui context ----------------
void Ui::onEvent(const InputEvent& e) {
    switch (e.type) {
        case InputEvent::Type::MouseMove: mx_ = e.x; my_ = e.y; break;
        case InputEvent::Type::MouseDown:
            mx_ = e.x; my_ = e.y;
            if (e.button == 1) { leftDown_ = true; pressed_ = 0; }
            if (e.button == 3) rightDown_ = true;
            break;
        case InputEvent::Type::MouseUp:
            if (e.button == 1) {
                leftDown_ = false;
                if (active_) released_ = active_; // click completes on the active widget
                active_ = 0;
            }
            if (e.button == 3) rightDown_ = false;
            break;
        case InputEvent::Type::Wheel: wheelDelta_ += e.wheelDelta; break;
        case InputEvent::Type::KeyDown:
            if ((int)e.key >= 0 && (int)e.key < (int)Key::F1 + 1) {
                keysDown_[(int)e.key] = true;
                keysPressed_.push_back(e.key);
            }
            break;
        case InputEvent::Type::KeyUp:
            if ((int)e.key >= 0 && (int)e.key < (int)Key::F1 + 1) keysDown_[(int)e.key] = false;
            break;
        case InputEvent::Type::Char:
            if (e.codepoint >= 32 && e.codepoint < 127) chars_ += (char)e.codepoint;
            if (e.codepoint == 8 || e.codepoint == 127) chars_ += '\b';
            if (e.codepoint == 13 || e.codepoint == 10) chars_ += '\r';
            break;
        default: break;
    }
}

bool Ui::keyPressed(Key k) const {
    for (Key kk : keysPressed_) if (kk == k) return true;
    return false;
}

void Ui::begin(Image* fb, float mouseX, float mouseY, bool leftDown, bool rightDown) {
    fb_ = fb;
    prevMx_ = mx_; prevMy_ = my_;
    mx_ = mouseX; my_ = mouseY;
    leftDown_ = leftDown;
    rightDown_ = rightDown;
    pressed_ = 0;
    released_ = 0;
    keysPressed_.clear();
    chars_.clear();
    wheelDelta_ = 0;
}

void Ui::clearFrameState() {
    // called by the editor after handling shortcuts to avoid double-use
    keysPressed_.clear();
}

void Ui::panel(int x, int y, int w, int h, Color bg) {
    fb_->fillRect(x, y, w, h, bg);
}

void Ui::rect(int x, int y, int w, int h, Color c) {
    fb_->fillRect(x, y, w, h, c);
}

void Ui::frame(int x, int y, int w, int h, Color c) {
    fb_->strokeRect(x, y, w, h, c, 1);
}

void Ui::label(const std::string& text, int x, int y, Color c, bool bold) {
    if (bold) uiFontBig().draw(*fb_, text, (float)x, (float)y, c);
    else uiFont().draw(*fb_, text, (float)x, (float)y, c);
}

bool Ui::button(unsigned id, const std::string& text, int x, int y, int w, int h,
                bool highlighted) {
    const Theme& t = Theme::get();
    bool hover = inRect(mx_, my_, x, y, w, h);
    bool act = active_ == id && leftDown_;
    Color bg = act ? t.accentDim : (hover || highlighted ? t.panelBg2 : t.panelBg);
    fb_->fillRect(x, y, w, h, bg);
    fb_->strokeRect(x, y, w, h, highlighted ? t.accent : t.border, 1);
    float tw = uiFont().textWidth(text);
    uiFont().draw(*fb_, text, x + (w - tw) * 0.5f, (float)y + (h - uiFont().height() * 0.72f) * 0.5f,
                  hover || highlighted ? t.text : t.textDim);
    if (hover) {
        if (leftDown_ && pressed_ == 0) { pressed_ = id; active_ = id; }
    }
    return hover && pressed_ == id && leftDown_;
}

bool Ui::checkbox(unsigned id, const std::string& text, int x, int y, bool value) {
    const Theme& t = Theme::get();
    bool hover = inRect(mx_, my_, x, y, 18, 18) || inRect(mx_, my_, x + 22, y - 2, (int)uiFont().textWidth(text) + 8, 18);
    fb_->fillRect(x, y, 16, 16, value ? t.accent : t.panelBg2);
    fb_->strokeRect(x, y, 16, 16, hover ? t.text : t.border, 1);
    if (value) {
        // check mark
        for (int i = 0; i < 7; ++i) {
            fb_->fillRect(x + 3 + i, y + 7 + i / 2, 2, 2, Color(255, 255, 255, 255));
            fb_->fillRect(x + 3 + i, y + 12 - i / 2, 2, 2, Color(255, 255, 255, 255));
        }
    }
    uiFont().draw(*fb_, text, (float)x + 22, (float)y + 2, t.text);
    if (hover && leftDown_ && pressed_ == 0) { pressed_ = id; }
    return hover && pressed_ == id && leftDown_;
}

float Ui::slider(unsigned id, const std::string& label, int x, int y, int w,
                 float value, float lo, float hi) {
    const Theme& t = Theme::get();
    int trackY = y + 10;
    fb_->fillRect(x, trackY, w, 4, t.panelBg2);
    float t01 = clampf((value - lo) / (hi - lo + 1e-6f), 0, 1);
    int hx = x + (int)(t01 * (w - 10));
    bool hover = inRect(mx_, my_, x - 4, y, w + 8, 22);
    fb_->fillRect(hx, trackY - 4, 10, 12, active_ == id || hover ? t.accent : t.textDim);
    uiFont().draw(*fb_, label, (float)x, (float)y + 14, t.textDim);
    if (hover && leftDown_) active_ = id;
    if (active_ == id && leftDown_) {
        float nv = lo + clampf((mx_ - x) / (float)w, 0, 1) * (hi - lo);
        if (std::fabs(nv - value) > (hi - lo) / 300.0f) return nv;
        return value;
    }
    return value;
}

int Ui::listbox(unsigned id, int x, int y, int w, int h,
                const std::vector<std::string>& items, int selected, int* scroll) {
    const Theme& t = Theme::get();
    fb_->fillRect(x, y, w, h, t.panelBg2);
    int rowH = 22;
    int visible = h / rowH;
    if (*scroll < 0) *scroll = 0;
    if (*scroll > (int)items.size() - visible) *scroll = std::max(0, (int)items.size() - visible);
    int clicked = -1;
    for (int i = 0; i < visible && *scroll + i < (int)items.size(); ++i) {
        int idx = *scroll + i;
        int ry = y + i * rowH;
        bool rowHover = inRect(mx_, my_, x, ry, w, rowH);
        if (idx == selected) fb_->fillRect(x + 1, ry + 1, w - 2, rowH - 2, t.accentDim);
        else if (rowHover) fb_->fillRect(x + 1, ry + 1, w - 2, rowH - 2, t.panelBg);
        uiFont().draw(*fb_, items[idx], (float)x + 8, (float)ry + 5, idx == selected ? t.text : t.textDim);
        if (rowHover && leftDown_ && pressed_ == 0) {
            pressed_ = id + (unsigned)idx;
            clicked = idx;
        }
    }
    return clicked;
}

bool Ui::textbox(unsigned id, std::string& value, int x, int y, int w) {
    const Theme& t = Theme::get();
    bool hover = inRect(mx_, my_, x, y, w, 20);
    bool focus = captured_ == id;
    fb_->fillRect(x, y, w, 20, t.panelBg2);
    fb_->strokeRect(x, y, w, 20, focus ? t.accent : (hover ? t.textDim : t.border), 1);
    uiFont().draw(*fb_, value, (float)x + 5, (float)y + 3, t.text);
    static int caretFrame = 0;
    if (focus && (++caretFrame / 24) % 2 == 0) {
        float cx = x + 5 + uiFont().textWidth(value);
        fb_->fillRect((int)cx, y + 3, 1, 14, t.text);
    }
    if (hover && leftDown_ && pressed_ == 0) { pressed_ = id; captured_ = id; }
    if (focus) {
        for (char c : chars_) {
            if (c == '\b') { if (!value.empty()) value.pop_back(); }
            else if (c == '\r') { captured_ = 0; return true; }
            else if (value.size() < 64) value += c;
        }
        if (keyPressed(Key::Escape)) { captured_ = 0; }
    }
    return false;
}

} // namespace leptid
